SELECT bs.state AS state, bs."in.nhgis_tract_gisjoin" AS nhgis_tract_gisjoin, sum(1) AS sample_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh__baseline", sum(up."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh__upgrade", sum((coalesce(bs."out.electricity.total.energy_consumption..kwh", 0) - coalesce(up."out.electricity.total.energy_consumption..kwh", 0)) * bs.weight) AS "electricity.total.energy_consumption..kwh__savings" FROM comstock_amy2018_r2_2025_md_by_state_and_county_parquet AS bs JOIN comstock_amy2018_r2_2025_md_by_state_and_county_parquet AS up ON bs.bldg_id = up.bldg_id AND bs."in.nhgis_tract_gisjoin" = up."in.nhgis_tract_gisjoin" AND bs.state = up.state AND bs.upgrade = 0 AND up.upgrade = 1 AND up.applicability = true WHERE bs.applicability = true AND bs.upgrade = 0 AND bs.state IN ('CO', 'NM') AND bs.bldg_id IN (7225, 7226, 7227, 7228, 7229, 7230, 7231, 7232, 7233, 7234, 7235, 7236, 7237, 7238, 7239, 7240) GROUP BY 1, 2 ORDER BY 1, 2